//! Recomputes every record of the shared arc test vectors (`../test/vectors/arc_vectors.txt`, generated by the C++
//! library and also checked by its gtest) and compares it with the expected values.

use std::fs;

use delivery_bot_geometry::{
    advance, angle_diff, closest_point, normalize_angle, point_at, tracking_error, Path, Pose2,
    Segment,
};

const TOL: f64 = 1e-9;
const VECTORS: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../test/vectors/arc_vectors.txt"
);

struct Record<'a> {
    line: &'a str,
    values: std::vec::IntoIter<f64>,
}

impl Record<'_> {
    fn next(&mut self) -> f64 {
        self.values
            .next()
            .unwrap_or_else(|| panic!("record too short: {}", self.line))
    }

    fn pose(&mut self) -> Pose2 {
        Pose2::new(self.next(), self.next(), self.next())
    }
}

fn near(actual: f64, expected: f64, what: &str, line: &str) {
    assert!(
        (actual - expected).abs() <= TOL,
        "{what}: {actual} != {expected} in `{line}`"
    );
}

fn near_angle(actual: f64, expected: f64, what: &str, line: &str) {
    assert!(
        angle_diff(actual, expected).abs() <= TOL,
        "{what}: {actual} != {expected} in `{line}`"
    );
}

fn near_pose(actual: &Pose2, expected: &Pose2, line: &str) {
    near(actual.x, expected.x, "x", line);
    near(actual.y, expected.y, "y", line);
    near_angle(actual.yaw, expected.yaw, "yaw", line);
}

#[test]
fn match_the_committed_file() {
    let text = fs::read_to_string(VECTORS).unwrap_or_else(|e| panic!("{VECTORS}: {e}"));
    let mut path = Path::default();
    let mut records = 0;
    for line in text
        .lines()
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
    {
        let mut words = line.split_whitespace();
        let kind = words.next().unwrap_or_default();
        let values: Vec<f64> = words
            .map(|w| w.parse().unwrap_or_else(|e| panic!("{e} in `{line}`")))
            .collect();
        let mut r = Record {
            line,
            values: values.into_iter(),
        };
        records += 1;
        match kind {
            "normalize" => {
                let a = r.next();
                near_angle(normalize_angle(a), r.next(), "normalize", line);
            }
            "compose" => {
                let a = r.pose();
                let b = r.pose();
                near_pose(&(a * b), &r.pose(), line);
            }
            "inverse" => {
                let a = r.pose();
                near_pose(&a.inverse(), &r.pose(), line);
            }
            "advance" => {
                let p = r.pose();
                let (k, l) = (r.next(), r.next());
                near_pose(&advance(&p, k, l), &r.pose(), line);
            }
            "path" => {
                let start = r.pose();
                let n = r.next();
                assert!(n >= 0.0 && n.fract() == 0.0, "segment count in `{line}`");
                let mut segments = Vec::new();
                while segments.len() as f64 + 0.5 < n {
                    segments.push(Segment::new(r.next(), r.next()));
                }
                path = Path::new(start, segments);
            }
            "length" => near(path.length(), r.next(), "length", line),
            "pose_at" => {
                let s = r.next();
                near_pose(&point_at(&path, s), &r.pose(), line);
            }
            "closest" => {
                let p = (r.next(), r.next());
                let (lo, hi) = (r.next(), r.next());
                let c = closest_point(&path, p, lo, hi);
                near(c.s, r.next(), "s", line);
                near_pose(&c.pose, &r.pose(), line);
                near(c.distance, r.next(), "distance", line);
            }
            "track" => {
                let robot = r.pose();
                let (lo, hi) = (r.next(), r.next());
                let e = tracking_error(&path, &robot, lo, hi);
                near(e.s, r.next(), "s", line);
                near(e.cross_track, r.next(), "cross_track", line);
                near_angle(e.heading, r.next(), "heading", line);
            }
            other => panic!("unknown record `{other}`"),
        }
        assert!(r.values.next().is_none(), "record too long: {line}");
    }
    assert!(records > 500, "only {records} records");
}
